/* Writers for union Cell: tag u32 (aligned 4), then the payload. */
hqqrpc_status edge_Cell_put_Int(hqqrpc_wr *w, int64_t v) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 1u);
    return st != HQQRPC_OK ? st : hqqrpc_wr_put_u64(w, (uint64_t)v);
}
hqqrpc_status edge_Cell_put_Text(hqqrpc_wr *w, const char *s, uint32_t n) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 2u);
    return st != HQQRPC_OK ? st : hqqrpc_wr_put_str(w, s, n, 4u);
}
hqqrpc_status edge_Cell_put_Nul(hqqrpc_wr *w) { return hqqrpc_wr_put_u32(w, 3u); }
hqqrpc_status edge_Cell_put_At(hqqrpc_wr *w, const edge_pt *v) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 4u);
    uint8_t *o;

    if (st != HQQRPC_OK)
        return st;
    if ((o = hqqrpc_wr_fixed(w, 8, 16)) == NULL)
        return w->err;
    memcpy(o, &(*v).x, 4);
    o[4] = (*v).ok ? 1u : 0u;
    memcpy(o + 8, &(*v).y, 8);
    return HQQRPC_OK;
}
hqqrpc_status edge_Cell_put_Arr(hqqrpc_wr *w, const int32_t *p, uint32_t n) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 5u);
    size_t mark;
    uint8_t *o;

    if (st != HQQRPC_OK || (st = hqqrpc_wr_array_begin(w, &mark)) != HQQRPC_OK)
        return st;
    if (n != 0) {
        if ((o = hqqrpc_wr_fixed(w, 4, (size_t)n * 4)) == NULL)
            return w->err;
        memcpy(o, p, (size_t)n * 4);
    }
    return hqqrpc_wr_array_end(w, mark, n, UINT32_MAX);
}
hqqrpc_status edge_Cell_put_Blob(hqqrpc_wr *w, const void *p, uint32_t n) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 6u);
    return st != HQQRPC_OK ? st : hqqrpc_wr_put_bytes(w, p, n, 4u);
}
hqqrpc_status edge_Cell_put_Real(hqqrpc_wr *w, double v) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 7u);
    uint8_t *o;

    if (st != HQQRPC_OK)
        return st;
    if ((o = hqqrpc_wr_fixed(w, 8, 8)) == NULL)
        return w->err;
    memcpy(o, &v, 8);
    return HQQRPC_OK;
}
hqqrpc_status edge_Cell_put_Byte(hqqrpc_wr *w, uint8_t v) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 8u);
    uint8_t *o;

    if (st != HQQRPC_OK)
        return st;
    if ((o = hqqrpc_wr_fixed(w, 1, 1)) == NULL)
        return w->err;
    memcpy(o, &v, 1);
    return HQQRPC_OK;
}
hqqrpc_status edge_Cell_put_Flag(hqqrpc_wr *w, bool v) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 9u);
    uint8_t *o;

    if (st != HQQRPC_OK)
        return st;
    if ((o = hqqrpc_wr_fixed(w, 1, 1)) == NULL)
        return w->err;
    o[0] = v ? 1u : 0u;
    return HQQRPC_OK;
}
hqqrpc_status edge_Cell_put_Words(hqqrpc_wr *w, const edge_pt *p, uint32_t n) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 10u);
    size_t mark;
    uint8_t *o;
    uint32_t i;

    if (st != HQQRPC_OK || (st = hqqrpc_wr_array_begin(w, &mark)) != HQQRPC_OK)
        return st;
    if (n != 0) {
        if ((o = hqqrpc_wr_fixed(w, 8, (size_t)n * 16)) == NULL)
            return w->err;
        for (i = 0; i < n; i++) {
            memcpy((o + i * 16), &p[i].x, 4);
            (o + i * 16)[4] = p[i].ok ? 1u : 0u;
            memcpy((o + i * 16) + 8, &p[i].y, 8);
        }
    }
    return hqqrpc_wr_array_end(w, mark, n, 2u);
}
hqqrpc_status edge_Cell_put_Quad(hqqrpc_wr *w, const uint8_t *p) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 11u);
    uint8_t *o;

    if (st != HQQRPC_OK)
        return st;
    if ((o = hqqrpc_wr_fixed(w, 1, 4)) == NULL)
        return w->err;
    memcpy(o, p, 4);
    return HQQRPC_OK;
}
hqqrpc_status edge_Cell_put_Small(hqqrpc_wr *w, int32_t v) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 12u);
    return st != HQQRPC_OK ? st : hqqrpc_wr_put_u32(w, (uint32_t)v);
}
hqqrpc_status edge_Cell_put_Wide(hqqrpc_wr *w, size_t v) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 13u);
    uint8_t *o;
    uint64_t sz;

    if (st != HQQRPC_OK)
        return st;
    if ((o = hqqrpc_wr_fixed(w, 8, 8)) == NULL)
        return w->err;
    sz = (uint64_t)v;
    memcpy(o, &sz, 8);
    return HQQRPC_OK;
}
